package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func caRecord(t *testing.T, ev map[string]interface{}) {
	b, err := json.Marshal(ev)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

// TestAssuranceVerifyLeaderUnderPartition measures the client-visible
// completion of VerifyLeader on a healthy leader and then on the same leader
// after it is isolated from its followers, with the leader lease set to one
// second so that the bounded completion path is the lease check.
func TestAssuranceVerifyLeaderUnderPartition(t *testing.T) {
	conf := inmemConfig(t)
	conf.HeartbeatTimeout = 300 * time.Millisecond
	conf.ElectionTimeout = 300 * time.Millisecond
	conf.LeaderLeaseTimeout = 300 * time.Millisecond

	c := MakeCluster(3, t, conf)
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader elected")
	}

	caRecord(t, map[string]interface{}{
		"event":        "verify_control_start",
		"node":         string(leader.localID),
		"leader_state": leader.getState().String(),
		"lease_ms":     conf.LeaderLeaseTimeout.Milliseconds(),
	})
	start := time.Now()
	healthyErr := leader.VerifyLeader().Error()
	healthyMs := time.Since(start).Milliseconds()
	caRecord(t, map[string]interface{}{
		"event":        "verify_healthy",
		"node":         string(leader.localID),
		"error_empty":  healthyErr == nil,
		"error_text":   errString2(healthyErr),
		"elapsed_ms":   healthyMs,
		"leader_state": leader.getState().String(),
	})

	// Isolate the leader from both followers; the other two stay connected.
	c.Partition([]ServerAddress{leader.localAddr})
	caRecord(t, map[string]interface{}{
		"event":           "verify_probe_start",
		"node":            string(leader.localID),
		"leader_state":    leader.getState().String(),
		"lease_ms":        conf.LeaderLeaseTimeout.Milliseconds(),
		"peers_connected": 0,
	})

	start = time.Now()
	future := leader.VerifyLeader()
	done := make(chan error, 1)
	go func() { done <- future.Error() }()
	var probeErr error
	completed := false
	select {
	case probeErr = <-done:
		completed = true
	case <-time.After(6 * time.Second):
	}
	elapsed := time.Since(start).Milliseconds()

	caRecord(t, map[string]interface{}{
		"event":         "verify_partitioned",
		"node":          string(leader.localID),
		"completed":     completed,
		"elapsed_ms":    elapsed,
		"error_empty":   completed && probeErr == nil,
		"error_text":    errString2(probeErr),
		"leader_state":  leader.getState().String(),
		"lease_ms":      conf.LeaderLeaseTimeout.Milliseconds(),
		"wait_limit_ms": 6000,
	})
}

func errString2(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func caSay(t *testing.T, ev map[string]interface{}) {
	b, err := json.Marshal(ev)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

// TestAssuranceConfigurationContentConvergence repeats the captured upgrade
// scenario and measures, per node, how long the atomically published
// configuration content takes to include the joining voter, and whether any
// node still showed the old membership while holding the configuration entry
// in its own log store. It deliberately avoids the configuration index
// accessor, which is known to return a constant zero.
func TestAssuranceConfigurationContentConvergence(t *testing.T) {
	const rounds = 25
	const window = 3 * time.Second

	for it := 0; it < rounds; it++ {
		conf := inmemConfig(t)
		conf.ProtocolVersion = 2
		c := MakeCluster(2, t, conf)

		conf3 := inmemConfig(t)
		conf3.ProtocolVersion = 3
		joiner := MakeClusterNoBootstrap(1, t, conf3)
		c.Merge(joiner)
		c.FullyConnect()

		leader := c.Leader()
		if leader == nil {
			t.Fatalf("round %d: no leader", it)
		}
		future := leader.AddVoter(joiner.rafts[0].localID, joiner.rafts[0].localAddr, 0, time.Second)
		if err := future.Error(); err != nil {
			t.Fatalf("round %d: add voter: %v", it, err)
		}
		entryIndex := future.Index()
		start := time.Now()

		caSay(t, map[string]interface{}{
			"event":        "config_round_probe_start",
			"iteration":    it,
			"entry_index":  entryIndex,
			"cluster_size": len(c.rafts),
		})

		for _, r := range c.rafts {
			logLast, _ := r.logs.LastIndex()
			caSay(t, map[string]interface{}{
				"event":                 "config_round_start",
				"iteration":             it,
				"node":                  string(r.localID),
				"entry_index":           entryIndex,
				"content_servers_start": len(r.getLatestConfiguration().Servers),
				"log_store_last_start":  logLast,
			})
		}

		convergedAt := map[ServerID]time.Duration{}
		deadline := start.Add(window)
		for time.Now().Before(deadline) {
			all := true
			for _, r := range c.rafts {
				_, done := convergedAt[r.localID]
				if !done {
					if len(r.getLatestConfiguration().Servers) >= 3 {
						convergedAt[r.localID] = time.Since(start)
					} else {
						all = false
					}
				}
			}
			if all {
				break
			}
			time.Sleep(5 * time.Millisecond)
		}

		anyLagWithEntry := false
		var maxWait int64
		type lagObs struct {
			node    string
			servers int
			present bool
			logLast uint64
			applied uint64
			commit  uint64
		}
		var lagging []lagObs
		for _, r := range c.rafts {
			var entry Log
			present := r.logs.GetLog(entryIndex, &entry) == nil
			logLast, _ := r.logs.LastIndex()
			servers := len(r.getLatestConfiguration().Servers)
			lat, ok := convergedAt[r.localID]
			if !ok && present {
				anyLagWithEntry = true
			}
			if lat.Milliseconds() > maxWait {
				maxWait = lat.Milliseconds()
			}
			caSay(t, map[string]interface{}{
				"event":                "config_node_result",
				"iteration":            it,
				"node":                 string(r.localID),
				"converged":            ok,
				"wait_ms":              lat.Milliseconds(),
				"content_servers":      servers,
				"entry_present_in_log": present,
				"log_store_last":       logLast,
				"applied_index":        r.getLastApplied(),
				"commit_index":         r.getCommitIndex(),
			})
			if !ok {
				lagging = append(lagging, lagObs{node: string(r.localID), servers: servers, present: present, logLast: logLast, applied: r.getLastApplied(), commit: r.getCommitIndex()})
			}
		}

		caSay(t, map[string]interface{}{
			"event":              "config_round_end",
			"iteration":          it,
			"entry_index":        entryIndex,
			"all_converged":      len(convergedAt) == len(c.rafts),
			"any_lag_with_entry": anyLagWithEntry,
			"max_wait_ms":        maxWait,
			"window_ms":          window.Milliseconds(),
			"lagging_nodes":      len(lagging),
		})
		c.Close()
	}
}

